contracts/interfaces/IConfigControllerFa.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "./IConfigController.sol";

/**
 * @title IConfigControllerFactory
 * @notice Interface for the ConfigControllerFactory contract
 * @dev This interface defines the functions and events for creating and managing ConfigController instances
 */
abstract contract IConfigControllerFactory {
    /// @notice Event emitted when a new ConfigController is created
    /// @param controller The address of the newly created controller
    /// @param owner The address of the controller owner
    /// @param guardian The address of the controller guardian
    /// @param sandboxController The address of the sandbox controller
    /// @param marketFactory The address of the market factory
    /// @param curatorFee The curator fee in basis points
    /// @param name The name of the controller
    /// @param curatorProposalDuration The duration of curator proposals in seconds
    /// @param proposalDuration The duration of market proposals in seconds
    event ConfigControllerCreated(
        address indexed controller,
        address indexed owner,
        address indexed guardian,
        address sandboxController,
        address marketFactory,
        uint curatorFee,
        string name,
        uint curatorProposalDuration,
        uint proposalDuration
    );

    /// @notice Returns the implementation address used for cloning
    /// @return The address of the implementation contract
    function implementation() external view virtual returns (address);

    /// @notice Returns the controller ID for a given config controller address
    /// @param configController The address of the config controller
    /// @return The ID of the controller
    function controllerIds(address configController) external view virtual returns (uint);

    /// @notice Returns the controller address at a given index
    /// @param index The index of the controller
    /// @return The address of the controller
    function controllerAddresses(uint index) external view virtual returns (address);

    /// @notice Returns the last controller ID
    /// @return The ID of the last controller
    function lastController() external view virtual returns (uint);

    /// @notice Creates a new ConfigController with the specified parameters
    /// @param owner_ The address of the controller owner
    /// @param guardian_ The address of the controller guardian
    /// @param _sandboxController The address of the sandbox controller
    /// @param _marketFactory The address of the market factory
    /// @param _curatorFee The curator fee in basis points
    /// @param _name The name of the controller
    /// @param _curatorProposalDuration The duration of curator proposals in seconds
    /// @param _proposalDuration The duration of market proposals in seconds
    /// @return The address of the newly created controller
    function createConfigController(
        address owner_,
        address guardian_,
        address _sandboxController,
        address _marketFactory,
        uint _curatorFee,
        string memory _name,
        uint _curatorProposalDuration,
        uint _proposalDuration
    ) external virtual returns (address);

    /// @notice Gets a ConfigController by its index
    /// @param _controllerId The index of the controller
    /// @return The address of the ConfigController
    function getController(uint _controllerId) external view virtual returns (address);

    /// @notice Checks if an address is a valid controller
    /// @param _controller The address to check
    /// @return True if the address is a valid controller
    function isController(address _controller) external view virtual returns (bool);
}

contracts/interfaces/ISandboxController..content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

abstract contract ISandboxController {
    enum MarketState {
        Low,
        Medium,
        High
    }

    struct BaseAssetCurve {
        uint64 supplyKink;
        uint64 supplyPerYearInterestRateBase;
        uint64 supplyPerYearInterestRateSlopeLow;
        uint64 supplyPerYearInterestRateSlopeHigh;
        uint64 borrowKink;
        uint64 borrowPerYearInterestRateBase;
        uint64 borrowPerYearInterestRateSlopeLow;
        uint64 borrowPerYearInterestRateSlopeHigh;
    }

    struct BaseAssetConfiguration {
        address priceFeed;
        uint8 decimals;
        uint256 minBorrow;
        BaseAssetCurve[] baseAssetCurves;
    }

    struct CollateralAssetConfiguration {
        address collateralToken;
        address priceFeed;
        uint8 decimals;
        uint64 maxBorrowCollateralFactor;
        uint64 minBorrowCollateralFactor;
        uint64 minLiquidateCollateralFactor;
        uint64 maxLiquidateCollateralFactor;
        uint64 minLiquidationFactor;
        uint64 maxLiquidationFactor;
    }

    struct SandboxControllerConfiguration {
        uint256 storeFrontPriceFactor;
        uint256 minUpdateTime;
        uint256 suggestedAmountOfSeedReserves;
        uint256 suggestedLockTimeOfSeedReserves;
    }

    error ZeroAddress();
    error InvalidFactors();
    error NotOwner(address);
    error NotDao(address);
    error NotAuthorized(address);
    error TokenAlreadyWhitelisted();
    error PriceFeedAlreadyWhitelisted();
    error InvalidCurveConfiguration();
    error InvalidPriceFeed();
    error TokenNotWhitelisted();

    event BaseAssetWhitelisted(
        address indexed token,
        address indexed priceFeed,
        uint8 decimals,
        BaseAssetCurve baseAssetCurve,
        uint256 minBorrow
    );
    event BaseAssetCurveAdded(address indexed token, BaseAssetCurve baseAssetCurve);
    event BaseAssetCurveChanged(address indexed token, BaseAssetCurve oldCurve, BaseAssetCurve newCurve);
    event CollateralAssetWhitelisted(
        address indexed token,
        address indexed priceFeed,
        uint256 decimals,
        uint64 maxBorrowCollateralFactor,
        uint64 minBorrowCollateralFactor,
        uint64 minLiquidateCollateralFactor,
        uint64 maxLiquidateCollateralFactor,
        uint64 minLiquidationFactor,
        uint64 maxLiquidationFactor
    );
    event TargetReservesChanged(uint256 oldTargetReserves, uint256 newTargetReserves);
    event ThresholdChanged(MarketState state, uint256 oldValue, uint256 newValue);
    event ReserveCommissionChanged(MarketState state, uint256 oldValue, uint256 newValue);
    event ProtocolCommissionChanged(MarketState state, uint256 oldValue, uint256 newValue);
    event TreasuryChanged(address oldTreasury, address newTreasury);
    event ConfigurationChanged(SandboxControllerConfiguration oldConfig, SandboxControllerConfiguration newConfig);
    event FeeEnabledSet(bool feeEnabled);
    event OwnerTransferred(address oldOwner, address newOwner);
    event DaoTransferred(address oldDao, address newDao);

    function protocolFactorBorrow() external view virtual returns (uint256);
    function reserveFactorBorrow() external view virtual returns (uint256);
    function protocolFactorLiquidation() external view virtual returns (uint256);
    function reserveFactorLiquidation() external view virtual returns (uint256);
    function maxCollateralAssets() external view virtual returns (uint256);
    function targetReserves() external view virtual returns (uint256);
    function baseAssetCount() external view virtual returns (uint256);
    function collateralAssetCount() external view virtual returns (uint256);
    function treasury() external view virtual returns (address);
    function owner() external view virtual returns (address);
    function dao() external view virtual returns (address);
    function feeEnabled() external view virtual returns (bool);
    function controllerConfiguration() external view virtual returns (SandboxControllerConfiguration memory);
    function baseAssetTokens(uint256) external view virtual returns (address);
    function collateralAssetTokens(uint256) external view virtual returns (address);
    function isPriceFeedWhitelisted(address) external view virtual returns (bool);
    function reserveCommission(MarketState) external view virtual returns (uint256);
    function protocolCommission(MarketState) external view virtual returns (uint256);
    function threshold(MarketState) external view virtual returns (uint256);

    function whitelistBaseAsset(
        address token,
        address priceFeed,
        BaseAssetCurve memory baseAssetCurve,
        uint256 minBorrow
    ) external virtual;

    function whitelistCollateralAsset(
        address token,
        address priceFeed,
        uint64 minBorrowCollateralFactor,
        uint64 maxBorrowCollateralFactor,
        uint64 minLiquidateCollateralFactor,
        uint64 maxLiquidateCollateralFactor,
        uint64 minLiquidationFactor,
        uint64 maxLiquidationFactor
    ) external virtual;

    function addBaseAssetCurve(address token, BaseAssetCurve memory baseAssetCurve) external virtual;
    function changeBaseAssetCurve(address token, uint256 curveIndex, BaseAssetCurve memory newCurve) external virtual;
    function setTargetReserves(uint256 _targetReserves) external virtual;
    function setThresholds(uint256[3] calldata thresholds) external virtual;
    function setReserveCommissions(uint256[3] calldata reserveCommissions) external virtual;
    function setProtocolCommissions(uint256[3] calldata protocolCommissions) external virtual;
    function setTreasury(address _treasury) external virtual;
    function setConfiguration(SandboxControllerConfiguration memory _config) external virtual;
    function setFeeEnabled(bool _feeEnabled) external virtual;
    function transferOwner(address newOwner) external virtual;
    function transferDao(address newDao) external virtual;
    function isBaseTokenWhitelisted(address token) external view virtual returns (bool);
    function isCollateralTokenWhitelisted(address token) external view virtual returns (bool);
    function isCurveConfigurationValid(BaseAssetCurve memory curve) external pure virtual returns (bool);
    function baseAssets(address token) external view virtual returns (BaseAssetConfiguration memory);
    function collateralAssets(address token) external view virtual returns (CollateralAssetConfiguration memory);
    function getBaseAssetCurves(address token) external view virtual returns (BaseAssetCurve[] memory);
}

contracts/interfaces/IMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import "./IConfigController.sol";

interface IMarket {
    struct BaseCurveParams {
        uint64 supplyKink;
        uint64 supplyPerYearInterestRateSlopeLow;
        uint64 supplyPerYearInterestRateSlopeHigh;
        uint64 supplyPerYearInterestRateBase;
        uint64 borrowKink;
        uint64 borrowPerYearInterestRateSlopeLow;
        uint64 borrowPerYearInterestRateSlopeHigh;
        uint64 borrowPerYearInterestRateBase;
    }

    // Individual market config variables
    function baseToken() external view returns (address);
    function priceFeed() external view returns (address);
    function baseTokenCurveId() external view returns (uint);
    function collateralTokensCount() external view returns (uint);

    // Base curve parameters
    function getBaseCurveParams() external view returns (BaseCurveParams memory);
    function setBaseCurveParams(BaseCurveParams memory _params) external;

    // Collateral token configuration
    function transferOwnership(address _newConfigController) external;
    function getCollateralTokenConfig(uint _collateralTokenId) external view returns (IConfigController.CollateralTokenConfig memory);
    function getAllCollateralTokenConfigs() external view returns (IConfigController.CollateralTokenConfig[] memory);
    function setCollateralTokens(IConfigController.CollateralTokenConfig[] memory _collateralTokens) external;
    function setCollateralTokenConfig(uint _index, IConfigController.CollateralTokenConfig memory _config) external;
    function setCollateralTokenSupplyCap(uint _index, uint128 _supplyCap) external;
    function setCollateralTokenBorrowCollateralFactor(uint _index, uint64 _borrowCF) external;
    function setCollateralTokenLiquidateCollateralFactor(uint _index, uint64 _liquidateCF) external;
    function setCollateralTokenLiquidationFactor(uint _index, uint64 _liquidationFactor) external;

    // Initialization
    function initialize(
        IConfigController.MarketConfig memory _marketConfig,
        address _configControllerAddress
    ) external;
}

contracts/interfaces/IMarketFactory.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.28;

import "./IConfigController.sol";

abstract contract IMarketFactory {
    event MarketCreated(address indexed market, address indexed configController);

    error Unauthorized();

    /// @notice Returns the implementation address used for cloning
    function implementation() external view virtual returns (address);

    /// @notice Returns the config controller address for a given market
    /// @param market The address of the market
    /// @return The address of the config controller
    function marketToController(address market) external view virtual returns (address);

    /// @notice Returns the config controller factory address
    function configControllerFactory() external view virtual returns (address);

    /// @notice Creates a new market with the specified configuration
    /// @param _marketConfig The configuration parameters for the new market
    /// @return The address of the newly created market
    function createMarket(IConfigController.MarketConfig memory _marketConfig) external virtual returns (address);

    /// @notice Returns the address of a market by its index
    /// @param index The index of the market
    /// @return The address of the market
    function markets(uint256 index) external view virtual returns (address);
}

